command:
const token = canvas.tokens.controlled[0] ?? game.user.character?.getActiveTokens()[0];
const actor = token?.actor ?? game.user.character;
if (!actor) return ui.notifications.warn("请先选中要举刀格挡的角色或令牌。");
const slug = "jiuli-parry";
const old = actor.itemTypes.effect.filter((e) => e.slug === slug);
if (old.length) await actor.deleteEmbeddedDocuments("Item", old.map((i) => i.id));
const effect = {
  name: "格挡（妖刀·隐里切）",
  type: "effect",
  img: "icons/skills/melee/sword-block-blue.webp",
  system: {
    slug,
    description: { value: "<p>举刀格架，直到你的下一回合开始获得 +1 环境 AC。</p>" },
    rules: [{ key: "FlatModifier", selector: "ac", type: "circumstance", value: 1, label: "格挡 Parry" }],
    traits: { value: ["magical"], rarity: "rare", otherTags: ["jiuli-katana"] },
    level: { value: 4 },
    duration: { value: 1, unit: "rounds", sustained: false, expiry: "turn-start" },
    tokenIcon: { show: true }
  }
};
await actor.createEmbeddedDocuments("Item", [effect]);
ui.notifications.info(`${actor.name}：格挡生效，+1 环境 AC（至你下回合开始）。`);
